function backendReady(){return Boolean(E.backendUrl&&/^https:\/\//.test(String(E.backendUrl)))}
function newRequestId(){try{return'v2_'+crypto.randomUUID()}catch{return'v2_'+Date.now()+'_'+Math.random().toString(36).slice(2)}}
function readPending(){try{const p=JSON.parse(localStorage.getItem(PENDING_KEY)||'null');if(!p||!p.requestId||Date.now()-Number(p.createdAt||0)>PENDING_TTL_MS){localStorage.removeItem(PENDING_KEY);return null}const phase=String(p.phase||'');if(!['prepared','dispatched','awaiting-result'].includes(phase)){localStorage.removeItem(PENDING_KEY);return null}return p}catch{try{localStorage.removeItem(PENDING_KEY)}catch{}return null}}
function recoverablePending(){const p=readPending();if(!p)return null;if(!['dispatched','awaiting-result'].includes(String(p.phase||''))){try{localStorage.removeItem(PENDING_KEY)}catch{}return null}return p}
function pendingFingerprint(body){return [body.operationalDate,body.mode,body.waitTypeId,body.adults,body.paidChildren,body.infants].map(v=>String(v??'')).join('|')}
function pendingSnapshot(body){return{operationalDate:body.operationalDate,mode:body.mode,waitTypeId:body.waitTypeId,adults:body.adults,paidChildren:body.paidChildren,infants:body.infants}}
function requestIdFor(body){const fingerprint=pendingFingerprint(body),old=readPending();if(old?.fingerprint===fingerprint){if(!old.body){try{localStorage.setItem(PENDING_KEY,JSON.stringify({...old,body:pendingSnapshot(body)}))}catch{}}return String(old.requestId)}const requestId=newRequestId();try{localStorage.setItem(PENDING_KEY,JSON.stringify({requestId,fingerprint,body:pendingSnapshot(body),phase:'prepared',createdAt:Date.now()}))}catch{}return requestId}
function setPendingPhase(requestId,phase){try{const p=readPending();if(!p||String(p.requestId)!==String(requestId))return;localStorage.setItem(PENDING_KEY,JSON.stringify({...p,phase:String(phase),updatedAt:Date.now(),...(phase==='dispatched'?{dispatchedAt:Date.now()}:{} )}))}catch{}}
function pendingBody(p=readPending()){if(!p)return null;if(p.body)return p.body;const a=String(p.fingerprint||'').split('|');if(a.length!==6)return null;return{operationalDate:a[0],mode:a[1],waitTypeId:a[2],adults:Number(a[3]),paidChildren:Number(a[4]),infants:Number(a[5])}}
function clearPending(requestId=''){try{const p=readPending();if(!requestId||!p||String(p.requestId)===String(requestId))localStorage.removeItem(PENDING_KEY)}catch{try{localStorage.removeItem(PENDING_KEY)}catch{}}}
async function withTimeout(promise,ms,message){let timer;try{return await Promise.race([promise,new Promise((_,reject)=>{timer=setTimeout(()=>reject(Error(message)),ms)})])}finally{clearTimeout(timer)}}

async function fetchWithTimeout(url,options={},ms=GET_TIMEOUT_MS,message='通信がタイムアウトしました。'){
  const ctrl=new AbortController();
  const timer=setTimeout(()=>ctrl.abort(),ms);
  try{return await fetch(url,{...options,signal:ctrl.signal})}
  catch(e){if(e?.name==='AbortError')throw Error(message);throw e}
  finally{clearTimeout(timer)}
}

async function gatewayGet(action,params={}){
  if(!backendReady())throw Error('NEW_GATEWAY_NOT_CONFIGURED');
  const u=new URL(E.backendUrl);u.searchParams.set('action',action);
  Object.entries(params).forEach(([k,v])=>u.searchParams.set(k,String(v??'')));u.searchParams.set('_',Date.now());
  const r=await fetchWithTimeout(u,{method:'GET',mode:'cors',credentials:'omit',cache:'no-store',headers:{Accept:'application/json'}},GET_TIMEOUT_MS,'受付状況の確認がタイムアウトしました。');
  let d;try{d=await r.json()}catch{throw Error(`Gateway response invalid (${r.status})`)}
  if(!r.ok&&action!=='requestStatus')throw Error(String(d?.error||`Gateway HTTP ${r.status}`));
  return d;
}

// requestStatus is answered only to the LINE user who owns the requestId.
async function requestStatusFor(id){
  if(!backendReady())throw Error('NEW_GATEWAY_NOT_CONFIGURED');
  let token='';try{token=String(window.liff?.getAccessToken?.()||'')}catch{}
  if(token.length<20)throw Error('LINE本人確認情報を取得できません。');
  const body=new URLSearchParams({action:'requestStatus',requestId:String(id||''),liffAccessToken:token});
  const r=await fetchWithTimeout(E.backendUrl,{method:'POST',mode:'cors',credentials:'omit',cache:'no-store',headers:{'Content-Type':'application/x-www-form-urlencoded;charset=UTF-8',Accept:'application/json'},body},GET_TIMEOUT_MS,'受付状況の確認がタイムアウトしました。');
  let d;try{d=await r.json()}catch{throw Error(`Gateway response invalid (${r.status})`)}
  return d;
}

async function pollRequest(id){
  const deadline=Date.now()+POLL_DEADLINE_MS;
  const waits=[350,650,1000,1500,2200,3000,4000];
  let i=0;
  while(Date.now()<deadline){
    await sleep(waits[Math.min(i,waits.length-1)]);i+=1;
    try{
      const r=await requestStatusFor(id);
      if(r&&r.found)return{...r,_requestId:id};
    }catch{}
  }
  const e=Error('受付結果を確認できません。AirWAIT側で成立している可能性があるため、新しい受付は行わないでください。');
  e.ambiguous=true;e.requestId=id;
  throw e;
}

async function post(action,body){
  const isCreate=action==='createReservation';
  const id=isCreate?requestIdFor(body):newRequestId(),payload={action,requestId:id,...body};
  const options={method:'POST',mode:'cors',credentials:'omit',cache:'no-store',headers:{'Content-Type':'application/x-www-form-urlencoded;charset=UTF-8',Accept:'application/json'},body:new URLSearchParams(Object.entries(payload).map(([k,v])=>[k,String(v??'')]))};
  let r;
  if(isCreate)setPendingPhase(id,'dispatched');
  try{
    r=await fetchWithTimeout(E.backendUrl,options,POST_TIMEOUT_MS,'受付送信の応答がタイムアウトしました。結果を確認します。');
  }catch{
    if(isCreate){setPendingPhase(id,'awaiting-result');setProcessingStage('verify')}
    return await pollRequest(id);
  }
  let d=null;try{d=await r.json()}catch{}
  if(d&&r.status!==202)return{...d,_requestId:id};
  if(isCreate){setPendingPhase(id,'awaiting-result');setProcessingStage('verify')}
  return await pollRequest(id);
}

function healthSupportsOfficialDevelop(h){
  if(!(h&&h.ok===true&&h.createRequiresVerifiedLiff===true&&h.createEnabled===true))return false;
  if(h.officialDevelopEnabled===true)return true;
  return Array.isArray(h.acceptedClientIds)&&h.acceptedClientIds.map(String).includes(String(E.channelId||''));
}
function lineState(){return typeof CTX?.lineState==='function'?CTX.lineState():{liffReady:false,inClient:false,booting:true}}
async function waitForLine(){let st=lineState();if(st.booting||!st.liffReady){await Promise.race([new Promise(resolve=>window.addEventListener('asoboon:v2-liff-ready',resolve,{once:true})),sleep(6000)]);st=lineState()}if(!st.liffReady)throw Error('LINE接続を確認できません。いったん閉じて開き直してください。');if(!st.inClient)throw Error('LINEミニアプリ内から開いてください。');if(!window.liff||!liff.isLoggedIn())throw Error('LINEログインを確認できません。')}
function developTestRule(){const t=E.developTestWaitType||{};if(E.environment!=='develop'||!t.waitTypeId)return null;return{waitTypeId:String(t.waitTypeId),label:String(t.label||'入場不可テスト'),detail:String(t.detail||'Developing専用テスト枠'),developTest:true}}
function isDevelopTestSlot(s){const t=developTestRule();return Boolean(t&&s&&String(s.waitTypeId)===String(t.waitTypeId))}
function usageAllowed(actual,{developTest=false}={}){const u=String(actual?.usageDispType||'');if(developTest)return !u||['01','02','KeyALL','KeySTORE_RECEPTION_ONLY'].includes(u);return !u||u==='01'||u==='02'||u==='KeyALL'||u==='KeySTORE_RECEPTION_ONLY'}
function buildSlots(waitTypes){const test=developTestRule(),configured=PRODUCTION_TEST_DISABLED?(test?[test]:[]):[...(S.day&&typeof R.slotsFor==='function'?R.slotsFor(S.day.businessType,S.mode):[])];return configured.map(rule=>{const actual=Array.isArray(waitTypes)?waitTypes.find(x=>String(x.waitTypeId||'')===String(rule.waitTypeId)):null;if(!actual)return null;if(rule.developTest){if(!usageAllowed(actual,{developTest:true}))return null;return{...rule,actual}}if(actual.dispFlg===false||!usageAllowed(actual))return null;return{...rule,actual}}).filter(Boolean)}
function nowJstTime(time){
 return new Intl.DateTimeFormat('ja-JP',{timeZone:'Asia/Tokyo',hour:'2-digit',minute:'2-digit',hourCycle:'h23'}).format(new Date(time));
}
function sameReceptionView(){return String(new URLSearchParams(location.search).get('view')||'home')==='reception'&&Boolean($('recSlots'))}
function cachedRemaining(){
 if(E.environment!=='production')return null;
 try{
   const v=JSON.parse(localStorage.getItem(CROWD_CACHE_KEY)||'null');
   if(!v||v.verifiedFresh!==true||!Array.isArray(v.details)||!Number.isFinite(v.savedAt))return null;
   if(Date.now()-v.savedAt<0||Date.now()-v.savedAt>CROWD_FRESH_MS)return null;
   if(String(v.operationalDate||'')!==String(S.day?.operationalDate||''))return null;
   if(String(v.businessType||'')!==String(S.day?.businessType||''))return null;
   return v;
 }catch{return null}
}
function readLineRemaining(waitTypeId){
 if(!Array.isArray(remainingDetails))return null;
 const name=LINE_REMAINING_NAMES[String(S.day?.businessType||'')]?.[String(waitTypeId||'')];
 if(!name)return null;
 const normalize=v=>String(v??'').normalize('NFKC').replace(/\s+/g,'').trim();
 const matches=remainingDetails.filter(row=>normalize(row?.detailedWaitType)===normalize(name));
 if(matches.length!==1||matches[0]?.reserveUnit!=='PERSON')return null;
 const row=matches[0],raw=row.remaining;
 if(typeof raw!=='number'&&!(typeof raw==='string'&&/^\d+$/.test(raw)))return null;
 const value=Number(raw);
 if(!Number.isSafeInteger(value)||value<0||value>350)return null;
 // Only an explicit verified 0 is safe: previous Workers turned null into 0.
 if(value===0&&row.remainingVerified!==true)return null;
 return value;
}
function updateRemainingInfo(){
 const panel=$('recRemainingInfo'),note=$('recRemainingNote'),button=$('recRemainingRefresh');
 if(!panel||!note)return;
 panel.hidden=PRODUCTION_TEST_DISABLED||!S.day||S.day.isClosed||!S.slots.length;
 if(panel.hidden)return;
 const known=Array.isArray(remainingDetails);
 note.textContent=remainingLoading?'LINE受付の残り人数を確認中…'
   :known?'LINE受付の残り目安 ／ '+nowJstTime(remainingCheckedAt)+' 確認'
   :'残り人数を確認できません。回は選択できます。';
 if(button){
   const remaining=remainingLastAttempt>0?Math.max(0,CROWD_MANUAL_COOLDOWN_MS-(performance.now()-remainingLastAttempt)):0;
   button.disabled=remainingLoading||S.busy||S.locked||remaining>0;
   if(remainingCooldownTimer){clearTimeout(remainingCooldownTimer);remainingCooldownTimer=0}
   // The real clock may be frozen in tests; monotonic time also survives
   // wall-clock changes on customer devices.
   if(remaining>0&&!remainingLoading&&!S.busy&&!S.locked){
     remainingCooldownTimer=setTimeout(()=>{
       remainingCooldownTimer=0;
       if(sameReceptionView())updateRemainingInfo();
     },remaining+60);
   }
 }
}
async function loadRemaining({force=false,generation=S.generation}={}){
 if(force&&remainingLastAttempt>0&&performance.now()-remainingLastAttempt<CROWD_MANUAL_COOLDOWN_MS)return;
 if(E.environment!=='production'||PRODUCTION_TEST_DISABLED||remainingLoading||!S.day||S.day.isClosed||!S.slots.length||!sameReceptionView()||S.busy||S.locked)return;
 if(!force){
   const cached=cachedRemaining();
   if(cached){remainingDetails=cached.details;remainingCheckedAt=cached.savedAt;renderSlots();updateRemainingInfo();return}
 }
 // A booking is never disabled based on a display-only crowd snapshot.
 remainingLoading=true;remainingLastAttempt=performance.now();updateRemainingInfo();
 const ctrl=new AbortController(),timer=setTimeout(()=>ctrl.abort(),8000);
 try{
   const url=new URL(String(E.backendUrl));url.searchParams.set('action','crowdRemaining');
   const response=await fetch(url,{method:'GET',credentials:'omit',cache:'no-store',signal:ctrl.signal});
   const data=await response.json();
   if(!response.ok||data?.ok!==true||data?.stale===true||!Array.isArray(data.observedDetails))throw Error('CROWD_UNAVAILABLE');
   if(generation!==S.generation||!sameReceptionView())return;
   remainingDetails=data.observedDetails;
   remainingCheckedAt=Date.now();
 }catch{
   if(generation!==S.generation||!sameReceptionView())return;
   // Never preserve stale counts after an unsuccessful fresh request.
   remainingDetails=null;remainingCheckedAt=0;
 }finally{
   clearTimeout(timer);remainingLoading=false;
   if(generation===S.generation&&sameReceptionView()&&!S.busy&&!S.locked){renderSlots();updateRemainingInfo()}
 }
}
function renderSlots(){const el=$('recSlots');if(!el)return;const hasTest=S.slots.some(isDevelopTestSlot);if(S.day?.isClosed&&!hasTest){el.innerHTML='<div class="rec-status bad">本日は休館日です。</div>';return}if(!lineReceptionOpenNow()&&!hasTest){el.innerHTML=`<div class="rec-status warn">LINE当日受付は${esc(lineOpenDisplay())}からです。受付開始後、本日のLINE受付枠をLINEから選べます。</div>`;scheduleLineOpen();return}if(!S.slots.length){el.innerHTML='<div class="rec-status warn">現在選択できる受付枠がありません。</div>';return}el.innerHTML=S.slots.map(s=>{
  const count=readLineRemaining(s.waitTypeId);
  const display=count===null?'確認中':count+'名';
  return `<button type="button" class="rec-slot ${S.slot?.waitTypeId===s.waitTypeId?'active':''}" data-rec-slot="${esc(s.waitTypeId)}" data-rec-available="1">
  <span class="rec-slot-main"><strong>${esc(s.developTest?'🧪 '+s.label:s.label)}</strong><small>${esc(s.actual?.waitTypeName||s.detail||'')}</small></span>
  ${E.environment!=='production'||PRODUCTION_TEST_DISABLED?'':`<span class="rec-slot-remaining ${count===null?'is-unknown':count===0?'is-zero':'is-known'}"><span>LINE受付 残り</span><b>${display}</b></span>`}
  </button>`;
 }).join('');updateRemainingInfo()}
function locationOk(){return LINE_STORE_ONLY||S.mode!=='onsite'||Boolean(S.location?.ok)}

